// Included inside udm after ThemeList/Form. Only the viewport is rendered;
// stable source identities and checkbox values remain in the batch model.
class BatchVirtualList:public ThemeList {
 std::vector<int> identities;std::map<std::pair<int,int>,std::wstring> cells;bool swallowClick=false;
 std::wstring& cell(int position,int column){const int id=rowId(position);const auto key=std::make_pair(id,column);auto found=cells.find(key);if(found==cells.end())found=cells.emplace(key,wide(textFor?textFor(id,column):std::string{})).first;return found->second;}
 UINT state(int position,UINT mask){UINT result=(UINT)ThemeList::WindowProc(LVM_GETITEMSTATE,position,mask&~LVIS_STATEIMAGEMASK);if((mask&LVIS_STATEIMAGEMASK)&&position>=0&&position<(int)identities.size())result|=INDEXTOSTATEIMAGEMASK(checked&&checked(rowId(position))?2:1);return result;}
 void copyText(int position,int column,wchar_t* target,int capacity){if(!target||capacity<=0)return;const auto& value=cell(position,column);const auto count=std::min(value.size(),static_cast<size_t>(capacity-1));std::copy_n(value.data(),count,target);target[count]=0;}
 void changeCheck(int position,bool value){if(position<0||position>=(int)identities.size())return;if(setChecked)setChecked(rowId(position),value);RedrawItems(position,position);}
 void restoreSelection(const std::set<int>& selected,int focused){ThemeList::WindowProc(LVM_SETITEMSTATE,-1,reinterpret_cast<LPARAM>(&emptySelection));for(int position=0;position<(int)identities.size();++position){UINT bits=(selected.count(identities[position])?LVIS_SELECTED:0)|(identities[position]==focused?LVIS_FOCUSED:0);if(bits){LVITEMW item{};item.stateMask=LVIS_SELECTED|LVIS_FOCUSED;item.state=bits;ThemeList::WindowProc(LVM_SETITEMSTATE,position,reinterpret_cast<LPARAM>(&item));}}}
 LVITEMW emptySelection=[] {LVITEMW item{};item.stateMask=LVIS_SELECTED|LVIS_FOCUSED;return item;}();
protected:
 LRESULT WindowProc(UINT message,WPARAM w,LPARAM l)override{
  if(message==LVM_GETITEMTEXTW){auto item=reinterpret_cast<LVITEMW*>(l);if((int)w<0||(int)w>=(int)identities.size())return 0;copyText((int)w,item->iSubItem,item->pszText,item->cchTextMax);return std::min(cell((int)w,item->iSubItem).size(),static_cast<size_t>(std::max(0,item->cchTextMax-1)));}
  if(message==LVM_GETITEMW){auto item=reinterpret_cast<LVITEMW*>(l);if(item->iItem<0||item->iItem>=(int)identities.size())return FALSE;if(item->mask&LVIF_PARAM)item->lParam=rowId(item->iItem);if(item->mask&LVIF_TEXT)copyText(item->iItem,item->iSubItem,item->pszText,item->cchTextMax);if(item->mask&LVIF_IMAGE)item->iImage=imageFor?imageFor(rowId(item->iItem)):I_IMAGENONE;if(item->mask&LVIF_STATE)item->state=state(item->iItem,item->stateMask);return TRUE;}
  if(message==LVM_SETITEMTEXTW){auto item=reinterpret_cast<LVITEMW*>(l);if((int)w<0||(int)w>=(int)identities.size())return FALSE;cells.erase({rowId((int)w),item->iSubItem});RedrawItems((int)w,(int)w);return TRUE;}
  if(message==LVM_SETITEMW){auto item=reinterpret_cast<LVITEMW*>(l);if(item->iItem<0||item->iItem>=(int)identities.size())return FALSE;if(item->mask&LVIF_PARAM)identities[item->iItem]=(int)item->lParam;if(item->mask&LVIF_TEXT)cells.erase({rowId(item->iItem),item->iSubItem});if(item->mask&LVIF_STATE)SendMessage(LVM_SETITEMSTATE,item->iItem,l);RedrawItems(item->iItem,item->iItem);return TRUE;}
  if(message==LVM_GETITEMSTATE)return state((int)w,(UINT)l);
  if(message==LVM_SETITEMSTATE){auto item=*reinterpret_cast<LVITEMW*>(l);if(item.stateMask&LVIS_STATEIMAGEMASK){const bool value=((item.state&LVIS_STATEIMAGEMASK)>>12)==2;if((int)w==-1){for(int position=0;position<(int)identities.size();++position)if(setChecked)setChecked(rowId(position),value);Invalidate(FALSE);}else changeCheck((int)w,value);item.stateMask&=~LVIS_STATEIMAGEMASK;item.state&=~LVIS_STATEIMAGEMASK;}return item.stateMask?ThemeList::WindowProc(message,w,reinterpret_cast<LPARAM>(&item)):TRUE;}
  if(message==LVM_SORTITEMS){const auto compare=reinterpret_cast<PFNLVCOMPARE>(l);std::set<int> selected;for(int p=GetNextItem(-1,LVNI_SELECTED);p>=0;p=GetNextItem(p,LVNI_SELECTED))selected.insert(rowId(p));const auto focused=GetNextItem(-1,LVNI_FOCUSED);const int focusId=focused<0?-1:rowId(focused);std::stable_sort(identities.begin(),identities.end(),[&](int a,int b){return compare(a,b,w)<0;});cells.clear();restoreSelection(selected,focusId);Invalidate(FALSE);return TRUE;}
  if((message==WM_LBUTTONDOWN||message==WM_LBUTTONDBLCLK)&&IsWindowEnabled()){LVHITTESTINFO hit{};hit.pt={static_cast<short>(LOWORD(l)),static_cast<short>(HIWORD(l))};const int position=SubItemHitTest(&hit);if(position>=0&&(hit.flags&LVHT_ONITEMSTATEICON)){SetFocus();SetItemState(position,LVIS_FOCUSED,LVIS_FOCUSED);changeCheck(position,!(checked&&checked(rowId(position))));swallowClick=true;return 0;}}
  if(message==WM_LBUTTONUP&&swallowClick){swallowClick=false;return 0;}
  if(message==WM_KEYDOWN&&w==VK_SPACE&&IsWindowEnabled()){const int position=GetNextItem(-1,LVNI_FOCUSED);if(position>=0)changeCheck(position,!(checked&&checked(rowId(position))));return 0;}
  return ThemeList::WindowProc(message,w,l);
 }
public:
 std::function<std::string(int,int)> textFor;std::function<bool(int)> checked;std::function<void(int,bool)> setChecked;std::function<int(int)> imageFor;
 int rowId(int position)const{return position>=0&&position<(int)identities.size()?identities[position]:-1;}
 void invalidateCells(){cells.clear();Invalidate(FALSE);}
 size_t cachedCellCount()const noexcept{return cells.size();}
 void setRows(const std::vector<int>& values){std::set<int> selected;for(int p=GetNextItem(-1,LVNI_SELECTED);p>=0;p=GetNextItem(p,LVNI_SELECTED))selected.insert(rowId(p));const auto focused=GetNextItem(-1,LVNI_FOCUSED);const int focusId=focused<0?-1:rowId(focused);identities=values;cells.clear();ThemeList::WindowProc(LVM_SETITEMCOUNT,identities.size(),LVSICF_NOINVALIDATEALL|LVSICF_NOSCROLL);restoreSelection(selected,focusId);Invalidate(FALSE);}
 void display(NMLVDISPINFOW& notice){auto& item=notice.item;if(item.iItem<0||item.iItem>=(int)identities.size())return;if(item.mask&LVIF_TEXT){auto& value=cell(item.iItem,item.iSubItem);item.pszText=value.data();}if(item.mask&LVIF_IMAGE)item.iImage=imageFor?imageFor(rowId(item.iItem)):I_IMAGENONE;if(item.mask&LVIF_STATE){item.stateMask|=LVIS_STATEIMAGEMASK;item.state=state(item.iItem,item.stateMask);}}
 int find(const NMLVFINDITEMW& notice){if(!(notice.lvfi.flags&(LVFI_STRING|LVFI_PARTIAL))||!notice.lvfi.psz)return -1;const auto needle=lower(utf8(notice.lvfi.psz));const int count=(int)identities.size(),start=std::max(0,notice.iStart);if(!count||start>=count)return -1;const int limit=(notice.lvfi.flags&LVFI_WRAP)?count:count-start;for(int offset=0;offset<limit;++offset){const int position=(start+offset)%count;const auto value=lower(textFor?textFor(rowId(position),0):std::string{});if((notice.lvfi.flags&LVFI_PARTIAL)?value.rfind(needle,0)==0:value==needle)return position;}return -1;}
};
